insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('b3000000-0000-4000-8000-000000000001', null, 'City Harvest', 'A rescue food nonprofit collecting surplus food from restaurants, grocers, and farms across the city and distributing it to New Yorkers facing hunger.', 'https://www.cityharvest.org', 'https://www.google.com/s2/favicons?domain=www.cityharvest.org&sz=128', 'food', array['good for crews', 'family friendly', 'counts for school hours'], false, false, 10, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000002', null, 'Food Bank For New York City', 'The largest hunger-relief organization in New York City, distributing food to hundreds of pantries and soup kitchens and running a major distribution center in the Bronx.', 'https://volunteer.foodbanknyc.org', 'https://www.google.com/s2/favicons?domain=volunteer.foodbanknyc.org&sz=128', 'food', array['good for crews', 'physical work'], false, false, 14, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000003', null, 'Central Park Conservancy', 'The nonprofit that manages and maintains Central Park, running regular volunteer days to keep the park beautiful for the millions who visit every year.', 'https://www.centralparknyc.org', 'https://www.google.com/s2/favicons?domain=www.centralparknyc.org&sz=128', 'environment', array['outdoors', 'good for crews', 'recurring'], false, false, 14, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000004', null, 'Brooklyn Bridge Park', 'A waterfront park spanning the Brooklyn shoreline, running the seasonal TIDES program that gives teens hands-on ecology and sustainability work right on the water.', 'https://brooklynbridgepark.org', 'https://www.google.com/s2/favicons?domain=brooklynbridgepark.org&sz=128', 'environment', array['recurring', 'leadership role', 'counts for school hours'], false, false, 14, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000005', null, 'Riverside Park Conservancy', 'The nonprofit steward of Riverside Park on Manhattan west side, running a summer Teen Corps that pairs teens with professional gardeners caring for the park.', 'https://riversideparknyc.org', 'https://www.google.com/s2/favicons?domain=riversideparknyc.org&sz=128', 'environment', array['recurring', 'outdoors', 'counts for school hours'], false, false, 14, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000006', null, 'NYC Parks Stewardship', 'The volunteer arm of the New York City Parks Department, coordinating community care for the city forests, wetlands, salt marshes, and street trees.', 'https://www.nycgovparks.org', 'https://www.google.com/s2/favicons?domain=www.nycgovparks.org&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000007', null, 'Mount Sinai Health System', 'A major New York hospital system that runs the Junior Medical Program (JuMP), an eight-week summer program letting high schoolers shadow healthcare professionals.', 'https://www.mountsinai.org', 'https://www.google.com/s2/favicons?domain=www.mountsinai.org&sz=128', 'medicine', array['leadership role', 'counts for school hours'], false, false, 15, 'United States', 'NY', 'New York', true, true, 'one-time', false),
  ('b3000000-0000-4000-8000-000000000008', null, 'NYU Langone Health', 'One of the top academic medical centers in the country, with volunteer programs across its New York City and Long Island campuses.', 'https://nyulangone.org', 'https://www.google.com/s2/favicons?domain=nyulangone.org&sz=128', 'medicine', array['recurring'], false, false, 16, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000009', null, 'NYC Health + Hospitals', 'The public hospital system serving every borough of New York City, running a structured summer volunteer program for high school students each year.', 'https://www.nychealthandhospitals.org', 'https://www.google.com/s2/favicons?domain=www.nychealthandhospitals.org&sz=128', 'medicine', array['counts for school hours'], false, false, 14, 'United States', 'NY', 'New York', true, true, 'one-time', false),
  ('b3000000-0000-4000-8000-000000000010', null, 'North Shore Animal League America', 'One of the largest no-kill animal rescue organizations in the world, based on Long Island and serving the greater New York City area.', 'https://www.animalleague.org', 'https://www.google.com/s2/favicons?domain=www.animalleague.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000011', null, 'Bideawee', 'A New York City animal welfare organization running adoption centers and pet care services, with a dedicated youth volunteer group for teens.', 'https://www.bideawee.org', 'https://www.google.com/s2/favicons?domain=www.bideawee.org&sz=128', 'animals', array['family friendly'], false, false, 13, 'United States', 'NY', 'New York', true, true, 'one-time', false),
  ('b3000000-0000-4000-8000-000000000012', null, 'Animal Care Centers of NYC', 'The organization contracted to run animal shelters in every borough of New York City, caring for tens of thousands of animals each year.', 'https://www.nycacc.org', 'https://www.google.com/s2/favicons?domain=www.nycacc.org&sz=128', 'animals', array['family friendly', 'recurring'], false, false, 6, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000013', null, 'New York Cares', 'The largest volunteer management organization in New York City, offering more than 1,000 different volunteer projects across every borough each year.', 'https://www.newyorkcares.org', 'https://www.google.com/s2/favicons?domain=www.newyorkcares.org&sz=128', 'community', array['recurring', 'family friendly'], false, false, 16, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000014', null, 'Jericho Project', 'A New York City nonprofit providing permanent supportive housing and services to homeless veterans and other vulnerable New Yorkers.', 'https://jerichoproject.org', 'https://www.google.com/s2/favicons?domain=jerichoproject.org&sz=128', 'veterans', array['recurring'], false, false, 18, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000015', null, 'Volunteers of America Greater New York', 'A nonprofit providing housing, food, and support services to New Yorkers experiencing homelessness, domestic violence, and other crises, including specific programs for seniors and veterans.', 'https://www.voa-gny.org', 'https://www.google.com/s2/favicons?domain=www.voa-gny.org&sz=128', 'community', array['recurring'], false, false, 18, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000016', null, 'The City Tutors', 'A New York City tutoring and mentoring community offering free, flexible academic and career support built for historically underserved students across all five boroughs.', 'https://www.thecitytutors.org', 'https://www.google.com/s2/favicons?domain=www.thecitytutors.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000017', null, 'East Harlem Tutorial Program', 'A nonprofit partnering with East Harlem public charter schools to provide tutoring, mentoring, and college-readiness support to students from elementary through high school.', 'https://www.ehtp.org', 'https://www.google.com/s2/favicons?domain=www.ehtp.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'NY', 'New York', true, true, 'ongoing', false),
  ('b3000000-0000-4000-8000-000000000018', null, 'Special Olympics New York', 'The largest state chapter of Special Olympics in the country, serving more than 51,000 athletes with year-round training and competition across 22 sports.', 'https://www.specialolympics-ny.org', 'https://www.google.com/s2/favicons?domain=www.specialolympics-ny.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000019', null, 'PowerPlayNYC', 'A New York City nonprofit using sports and fitness programming to build confidence and leadership skills in girls across the city.', 'https://powerplaynyc.org', 'https://www.google.com/s2/favicons?domain=powerplaynyc.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'NY', 'New York', true, true, 'both', false),
  ('b3000000-0000-4000-8000-000000000020', null, 'The Metropolitan Museum of Art', 'One of the largest and most visited art museums in the world, relying on a corps of more than 1,250 volunteers to support galleries, tours, and public programs.', 'https://www.metmuseum.org', 'https://www.google.com/s2/favicons?domain=www.metmuseum.org&sz=128', 'art', array['recurring'], false, false, 18, 'United States', 'NY', 'New York', true, true, 'ongoing', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('b4000000-0000-4000-8000-000000000001', 'b3000000-0000-4000-8000-000000000001', 'Repack Food with City Harvest', 'food', 'Volunteers ages 10 and up help repack rescued food from large containers into family-sized bags at City Harvest facilities, ready for distribution to food pantries and soup kitchens citywide. It is one of the most kid-and-family-friendly hunger-relief options in the city, and groups are welcome.', array['good for crews', 'family friendly', 'counts for school hours'], 10, false, false, true, '2-3 hrs', 'https://www.cityharvest.org/youth-opportunities/', 'https://www.cityharvest.org/youth-opportunities/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000002', 'b3000000-0000-4000-8000-000000000002', 'Sort and Pack Food at the Bronx Distribution Center', 'food', 'Volunteers sort and repack food at Food Bank For New York City main distribution center, playing a hands-on role in getting food ready to reach communities across the five boroughs. Some in-person projects can accommodate younger volunteers, with exact age minimums listed on each specific opportunity.', array['good for crews', 'physical work'], 14, false, false, true, '2-3 hrs', 'https://volunteer.foodbanknyc.org/', 'https://volunteer.foodbanknyc.org/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000003', 'b3000000-0000-4000-8000-000000000003', 'Help Maintain and Beautify Central Park', 'environment', 'Teen and adult volunteers work alongside Conservancy staff on weekend workdays doing planting, weeding, and general park upkeep across Central Park. It is a great option if you want a recurring, visible project in one of the most iconic public spaces in the world.', array['outdoors', 'good for crews', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://www.centralparknyc.org/volunteer', 'https://www.centralparknyc.org/volunteer', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000004', 'b3000000-0000-4000-8000-000000000004', 'Join TIDES at Brooklyn Bridge Park', 'environment', 'TIDES is a seasonal after-school program where high schoolers complete weekly community service projects focused on ecology, conservation, and sustainability along the Brooklyn waterfront. Teens who complete the Stewardship tier can continue into a teen leadership apprenticeship supporting environmental education programs in the park.', array['recurring', 'leadership role', 'counts for school hours'], 14, false, false, true, '2-3 hrs / week', 'https://brooklynbridgepark.org/education/teen-programs/', 'https://brooklynbridgepark.org/education/teen-programs/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000005', 'b3000000-0000-4000-8000-000000000005', 'Join the Riverside Park Teen Corps', 'environment', 'Teen Corps members meet twice a week through the summer to work alongside zone gardeners maintaining horticultural sites and managing woodland areas of Riverside Park. Volunteers who complete 48 hours of service over the summer receive a stipend, making this a rare paid-adjacent option for consistent outdoor service.', array['recurring', 'outdoors', 'counts for school hours'], 14, false, false, true, '2 mornings / week', 'https://riversideparknyc.org/job/youth-opportunity-teen-corps/', 'https://riversideparknyc.org/job/youth-opportunity-teen-corps/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000006', 'b3000000-0000-4000-8000-000000000006', 'Volunteer for a NYC Parks Stewardship Event', 'environment', 'Volunteers can join tree and shrub plantings, invasive plant removal, and trail restoration events across parks in every borough, with events posted regularly throughout the year on the Parks Department site. It is one of the easiest ways to find a drop-in outdoor project close to home no matter which borough you are in.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://www.nycgovparks.org/opportunities/volunteer/groups/conservation', 'https://www.nycgovparks.org/opportunities/volunteer/groups/conservation', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000007', 'b3000000-0000-4000-8000-000000000007', 'Join the Mount Sinai Junior Medical Program', 'medicine', 'JuMP is an eight-week summer program for students 15 to 17 that combines a 100-hour volunteer commitment with direct exposure to how a hospital actually runs, from patient support to shadowing staff. It is a strong pick if you are seriously considering a healthcare career and want real hospital experience.', array['leadership role', 'counts for school hours'], 15, false, false, true, '100 hrs total', 'https://www.mountsinai.org/locations/morningside/about/volunteer', 'https://www.mountsinai.org/locations/morningside/about/volunteer', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000008', 'b3000000-0000-4000-8000-000000000008', 'Volunteer at NYU Langone', 'medicine', 'High school and college students support patient services and hospital operations across NYU Langone many campus locations, with roles ranging from patient companionship to administrative support. It is a good option if you want ongoing hospital experience closer to home rather than a single summer program.', array['recurring'], 16, false, false, true, 'Varies', 'https://nyulangone.org/volunteer', 'https://nyulangone.org/volunteer', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000009', 'b3000000-0000-4000-8000-000000000009', 'Join the NYC Health + Hospitals Summer Program', 'medicine', 'The summer program runs from the first week of July to mid-August at hospital facilities across the five boroughs, giving high schoolers real exposure to public healthcare. It is one of the more accessible hospital programs since NYC Health + Hospitals has a location in nearly every borough.', array['counts for school hours'], 14, false, false, true, 'Summer program', 'https://www.nychealthandhospitals.org/volunteering/', 'https://www.nychealthandhospitals.org/volunteering/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000010', 'b3000000-0000-4000-8000-000000000010', 'Join the VolunTEEN Program', 'animals', 'VolunTEENs ages 16-17 commit to 2-4 hours a week for 3-4 months, helping shelter staff with cleaning, feeding, and socializing homeless dogs, cats, puppies, and kittens. It is a great option if you want a real recurring responsibility rather than a one-time visit.', array['recurring'], 16, false, false, true, '2-4 hrs / week', 'https://www.animalleague.org/get-involved/volunteer/', 'https://www.animalleague.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000011', 'b3000000-0000-4000-8000-000000000011', 'Join the Bideawee Teen Volunteer Group', 'animals', 'The teen group, open to ages 13-17, runs on select summer Fridays and includes cleaning tasks, organizational projects, and hands-on socialization time with adoptable animals. It is a lower-commitment way to get real shelter experience without a long-term schedule.', array['family friendly'], 13, false, false, true, '2-3 hrs', 'https://www.bideawee.org/programs/volunteer/', 'https://www.bideawee.org/programs/volunteer/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000012', 'b3000000-0000-4000-8000-000000000012', 'Volunteer in an NYC Animal Shelter', 'animals', 'ACC welcomes young people between 6 and 17 to volunteer inside its shelters helping animals feel comfortable through socialization, enrichment activities, and basic care support alongside staff. It is one of the only shelter programs in the city open to volunteers this young, making it great for families.', array['family friendly', 'recurring'], 6, false, false, true, '2 hrs', 'https://www.nycacc.org/volunteer/', 'https://www.nycacc.org/volunteer/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000013', 'b3000000-0000-4000-8000-000000000013', 'Find a New York Cares Project', 'community', 'New York Cares posts a huge range of one-time and ongoing projects, from Step Up Tutoring for elementary students to phone-banking wellness checks for veterans and seniors, so you can browse and pick whatever fits your interests and schedule. It is the best single place to start if you are not sure yet which cause you want to focus on in NYC.', array['recurring', 'family friendly'], 16, false, false, true, 'Varies', 'https://www.newyorkcares.org/volunteers', 'https://www.newyorkcares.org/volunteers', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000014', 'b3000000-0000-4000-8000-000000000014', 'Support the Jericho Project Veterans Initiative', 'veterans', 'Jericho has helped house and support more than 700 veterans, and volunteers assist with programs that help veterans stabilize housing and rebuild independence. It is a meaningful option if you specifically want your service to support veterans experiencing homelessness.', array['recurring'], 18, false, false, true, 'Varies', 'https://jerichoproject.org/programs-services/veterans-initiative/', 'https://jerichoproject.org/programs-services/veterans-initiative/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000015', 'b3000000-0000-4000-8000-000000000015', 'Volunteer with VOA Greater New York', 'community', 'VOA-GNY runs programs across housing, food security, and family support, and welcomes volunteers to help with everything from meal service to program support at its sites around the city. It is a broad, established organization if you want to support multiple vulnerable populations under one roof.', array['recurring'], 18, false, false, true, 'Varies', 'https://www.voa-gny.org/', 'https://www.voa-gny.org/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000016', 'b3000000-0000-4000-8000-000000000016', 'Tutor or Mentor with The City Tutors', 'education', 'Volunteers tutor students in academic subjects or serve as career mentors, with flexible scheduling designed to work around a normal school or work week. It is a good match if you want tutoring experience but need a program that will not demand a rigid weekly slot.', array['recurring', 'counts for school hours'], 16, false, false, true, 'Flexible', 'https://www.thecitytutors.org/volunteer', 'https://www.thecitytutors.org/volunteer', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000017', 'b3000000-0000-4000-8000-000000000017', 'Tutor or Mentor at East Harlem Tutorial Program', 'education', 'Volunteers support students through subject-matter tutoring, homework help, general mentoring, or college-readiness coaching for high schoolers, working directly inside partner schools and after-school programs. It is a strong option if you want to see your tutoring connect to a specific, consistent school community.', array['recurring', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://www.ehtp.org/volunteer', 'https://www.ehtp.org/volunteer', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000018', 'b3000000-0000-4000-8000-000000000018', 'Coach or Volunteer with Special Olympics New York', 'sports', 'Volunteer coaches make it possible for athletes to train and compete across 22 different sports, and no prior coaching experience is required since full training is provided. Volunteers who have close, regular contact with athletes must be at least 16, and the organization is actively recruiting new coaches across all five boroughs.', array['recurring', 'leadership role'], 16, false, false, true, '1-2 hrs / week', 'https://www.specialolympics-ny.org/get-involved/volunteer/', 'https://www.specialolympics-ny.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000019', 'b3000000-0000-4000-8000-000000000019', 'Volunteer with PowerPlayNYC', 'sports', 'Volunteers help lead and support sports and fitness sessions designed specifically to build confidence, teamwork, and leadership in girls, with programs running at partner sites around the city. It is a good fit if you care specifically about girls empowerment through athletics.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://powerplaynyc.org/become-a-volunteer/', 'https://powerplaynyc.org/become-a-volunteer/', '2026-01-01T00:00:00Z', 'New York', 'NY'),
  ('b4000000-0000-4000-8000-000000000020', 'b3000000-0000-4000-8000-000000000020', 'Volunteer at the Met', 'art', 'Volunteers help visitors throughout the museum and library and support events and public programs, with full training provided and no prior museum experience required. Standard volunteer positions are for adults 18 and up, so this is one to bookmark for college rather than high school.', array['recurring'], 18, false, false, true, 'Varies', 'https://www.metmuseum.org/support/volunteer', 'https://www.metmuseum.org/support/volunteer', '2026-01-01T00:00:00Z', 'New York', 'NY')
on conflict (id) do nothing;

