values
  ('c5000000-0000-4000-8000-000000000001', null, 'LA Regional Food Bank', 'The largest hunger-relief organization in Los Angeles County, distributing food through a network of more than 600 partner agencies across the region.', 'https://www.lafoodbank.org', 'https://www.google.com/s2/favicons?domain=www.lafoodbank.org&sz=128', 'food', array['good for crews', 'physical work'], false, false, 14, 'United States', 'CA', 'Los Angeles', true, true, 'both', false),
  ('c5000000-0000-4000-8000-000000000002', null, 'Hope for LA', 'A Los Angeles nonprofit connecting volunteers with hands-on service projects supporting people experiencing poverty and homelessness across the city.', 'https://hopeforla.org', 'https://www.google.com/s2/favicons?domain=hopeforla.org&sz=128', 'community', array['good for crews', 'family friendly'], false, false, 12, 'United States', 'CA', 'Los Angeles', true, true, 'both', false),
  ('c5000000-0000-4000-8000-000000000003', null, 'Heal the Bay', 'A leading Los Angeles environmental nonprofit working to make the coastal waters and watersheds of Greater LA safe, healthy, and clean.', 'https://healthebay.org', 'https://www.google.com/s2/favicons?domain=healthebay.org&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'CA', 'Los Angeles', true, true, 'both', false),
  ('c5000000-0000-4000-8000-000000000004', null, 'LA Waterkeeper', 'A nonprofit working to protect and restore the coastal waters, rivers, and watersheds of the Los Angeles region through restoration, monitoring, and advocacy.', 'https://www.lawaterkeeper.org', 'https://www.google.com/s2/favicons?domain=www.lawaterkeeper.org&sz=128', 'environment', array['outdoors', 'physical work'], false, false, 14, 'United States', 'CA', 'Los Angeles', true, true, 'both', false),
  ('c5000000-0000-4000-8000-000000000005', null, 'City of Los Angeles Recreation and Parks', 'The city department managing parks across Los Angeles, coordinating volunteer clean-up efforts, tree planting, and invasive plant removal at local parks.', 'https://recreation.parks.lacity.gov', 'https://www.google.com/s2/favicons?domain=recreation.parks.lacity.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'CA', 'Los Angeles', true, true, 'both', false),
  ('c5000000-0000-4000-8000-000000000006', null, 'Children''s Hospital Los Angeles', 'A leading pediatric hospital running a structured seven-week High School Summer Volunteer Program each year for local students.', 'https://www.chla.org', 'https://www.google.com/s2/favicons?domain=www.chla.org&sz=128', 'medicine', array['counts for school hours', 'leadership role'], false, false, 15, 'United States', 'CA', 'Los Angeles', true, true, 'one-time', false),
  ('c5000000-0000-4000-8000-000000000007', null, 'Cedars-Sinai', 'One of the largest nonprofit academic medical centers in the western United States, running a dedicated high school volunteer program each year.', 'https://www.cedars-sinai.org', 'https://www.google.com/s2/favicons?domain=www.cedars-sinai.org&sz=128', 'medicine', array['counts for school hours'], false, false, 14, 'United States', 'CA', 'Los Angeles', true, true, 'one-time', false),
  ('c5000000-0000-4000-8000-000000000008', null, 'UCLA Health', 'The academic medical center of UCLA, offering high school student volunteer programs including patient transport roles that expose students to nearly every part of the hospital.', 'https://www.uclahealth.org', 'https://www.google.com/s2/favicons?domain=www.uclahealth.org&sz=128', 'medicine', array['counts for school hours'], false, false, 15, 'United States', 'CA', 'Los Angeles', true, true, 'one-time', false),
  ('c5000000-0000-4000-8000-000000000009', null, 'Keck Medicine of USC', 'The academic medical enterprise of USC, running a Summer Youth Volunteer Program each year at Keck Hospital and USC Norris Cancer Hospital.', 'https://www.keckmedicine.org', 'https://www.google.com/s2/favicons?domain=www.keckmedicine.org&sz=128', 'medicine', array['counts for school hours'], false, false, 16, 'United States', 'CA', 'Los Angeles', true, true, 'one-time', false),
  ('c5000000-0000-4000-8000-000000000010', null, 'Pasadena Humane', 'A major animal shelter and adoption center serving the Pasadena and San Gabriel Valley area, with a dedicated volunteer track for kids and younger teens.', 'https://pasadenahumane.org', 'https://www.google.com/s2/favicons?domain=pasadenahumane.org&sz=128', 'animals', array['family friendly', 'recurring'], false, false, 0, 'United States', 'CA', 'Pasadena', true, true, 'ongoing', false),
  ('c5000000-0000-4000-8000-000000000011', null, 'LA County Animal Care and Control', 'The public agency operating animal shelters across Los Angeles County, caring for tens of thousands of animals each year with the help of volunteers.', 'https://animalcare.lacounty.gov', 'https://www.google.com/s2/favicons?domain=animalcare.lacounty.gov&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'CA', 'Los Angeles', true, true, 'ongoing', false),
  ('c5000000-0000-4000-8000-000000000012', null, 'Pet Orphans of Southern California', 'A no-kill animal rescue and adoption organization serving Southern California, relying on volunteers for shelter care and adoption events.', 'https://petorphans.org', 'https://www.google.com/s2/favicons?domain=petorphans.org&sz=128', 'animals', array['counts for school hours', 'recurring'], false, false, 14, 'United States', 'CA', 'Los Angeles', true, true, 'ongoing', false),
  ('c5000000-0000-4000-8000-000000000013', null, 'spcaLA', 'A Southern California animal welfare organization running shelter operations along with humane education and violence-prevention youth programs.', 'https://spcala.com', 'https://www.google.com/s2/favicons?domain=spcala.com&sz=128', 'animals', array['recurring'], false, false, 14, 'United States', 'CA', 'Los Angeles', true, true, 'both', false),
  ('c5000000-0000-4000-8000-000000000014', null, 'The Mission Continues', 'A national nonprofit that mobilizes veterans to continue serving their communities, with an active Los Angeles platoon working in underserved neighborhoods.', 'https://www.missioncontinues.org', 'https://www.google.com/s2/favicons?domain=www.missioncontinues.org&sz=128', 'veterans', array['leadership role', 'good for crews'], false, false, 18, 'United States', 'CA', 'Los Angeles', true, true, 'ongoing', false),
  ('c5000000-0000-4000-8000-000000000015', null, 'Reading Partners Los Angeles', 'A literacy nonprofit pairing trained volunteers with elementary students who need extra reading support, working through partner schools across Los Angeles.', 'https://readingpartners.org', 'https://www.google.com/s2/favicons?domain=readingpartners.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'CA', 'Los Angeles', true, true, 'ongoing', false),
  ('c5000000-0000-4000-8000-000000000016', null, 'Step Up Tutoring', 'A tutoring nonprofit that partners with LAUSD to match students with consistent, caring online tutors for twice-weekly sessions.', 'https://www.stepuptutoring.org', 'https://www.google.com/s2/favicons?domain=www.stepuptutoring.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'CA', 'Los Angeles', true, true, 'ongoing', false),
  ('c5000000-0000-4000-8000-000000000017', null, 'School on Wheels', 'A Los Angeles nonprofit connecting volunteer tutors directly with children experiencing homelessness to provide consistent one-on-one academic support.', 'https://schoolonwheels.org', 'https://www.google.com/s2/favicons?domain=schoolonwheels.org&sz=128', 'education', array['recurring'], false, false, 16, 'United States', 'CA', 'Los Angeles', true, true, 'ongoing', false),
  ('c5000000-0000-4000-8000-000000000018', null, 'Special Olympics Southern California', 'The Southern California chapter of Special Olympics, providing year-round sports training and competition for athletes with intellectual disabilities across the region.', 'https://sosc.org', 'https://www.google.com/s2/favicons?domain=sosc.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 14, 'United States', 'CA', 'Los Angeles', true, true, 'both', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('c6000000-0000-4000-8000-000000000001', 'c5000000-0000-4000-8000-000000000001', 'Sort and Box Food at the LA Food Bank', 'food', 'Volunteers box, sort, and glean food at the Food Bank facility, which then moves out through partner pantries and agencies to neighbors across LA County. Standard volunteer shifts are open to ages 14 and up, and all volunteers register online before their first shift.', array['good for crews', 'physical work'], 14, false, false, true, '2-3 hrs', 'https://www.lafoodbank.org/volunteer/', 'https://www.lafoodbank.org/volunteer/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000002', 'c5000000-0000-4000-8000-000000000002', 'Get Involved with Hope for LA', 'community', 'Hope for LA organizes group service projects ranging from meal prep to care kit assembly to direct outreach, making it an easy option for families, clubs, or classes looking for a single group project. Check the site for current project dates and any age notes for each one.', array['good for crews', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://hopeforla.org/get-involved/', 'https://hopeforla.org/get-involved/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000003', 'c5000000-0000-4000-8000-000000000003', 'Join a Heal the Bay Cleanup or Youth Program', 'environment', 'Heal the Bay runs beach cleanups, aquarium volunteering, community science monitoring, and dedicated youth programs, with a volunteer orientation to help you find the track that fits you best. It is a great starting point if you are not sure yet whether you want ocean science, outreach, or hands-on cleanup work.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://healthebay.org/take-part/', 'https://healthebay.org/take-part/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000004', 'c5000000-0000-4000-8000-000000000004', 'Restore LA Waterways with LA Waterkeeper', 'environment', 'Volunteers take part in restoration projects and cleanups along LA rivers and coastal waters, directly supporting the health of local watersheds. It is a strong pick if you are specifically interested in water quality and river restoration rather than general park cleanups.', array['outdoors', 'physical work'], 14, false, false, true, '2-3 hrs', 'https://www.lawaterkeeper.org/volunteer', 'https://www.lawaterkeeper.org/volunteer', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000005', 'c5000000-0000-4000-8000-000000000005', 'Volunteer at a Local LA Park', 'environment', 'Volunteers help with clean-up efforts, tree planting, and pulling invasive weeds at parks across the city, with your nearest Recreation and Parks facility able to walk you through current openings and the application process. It is one of the easiest ways to find a project within walking distance of home.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://recreation.parks.lacity.gov/volunteer/volunteer-opportunities', 'https://recreation.parks.lacity.gov/volunteer/volunteer-opportunities', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000006', 'c5000000-0000-4000-8000-000000000006', 'Join the CHLA High School Summer Program', 'medicine', 'The program runs seven weeks each summer for students 15 to 17 who have completed their freshman year, with participants completing 112 service hours across the hospital. It is a serious, structured option if you want real pediatric hospital exposure over a full summer.', array['counts for school hours', 'leadership role'], 15, false, false, true, '112 hrs total', 'https://www.chla.org/volunteering-hospital/high-school-summer-volunteer-program', 'https://www.chla.org/volunteering-hospital/high-school-summer-volunteer-program', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000007', 'c5000000-0000-4000-8000-000000000007', 'Volunteer as a Cedars-Sinai High School Student', 'medicine', 'High school students 14 to 17 apply for either a clinical or clerical track and commit to completing 100 hours of service over the program. It is a good option if you want to compare a clinical, patient-facing role against a behind-the-scenes clerical one.', array['counts for school hours'], 14, false, false, true, '100 hrs total', 'https://www.cedars-sinai.org/volunteer-services/high-school-students.html', 'https://www.cedars-sinai.org/volunteer-services/high-school-students.html', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000008', 'c5000000-0000-4000-8000-000000000008', 'Volunteer as a UCLA Health High School Student', 'medicine', 'High school volunteers can take on roles like patient transport, helping discharge and move patients around the hospital alongside transport staff, giving broad exposure to how a large academic hospital runs. It is a strong option if you want to see many different departments rather than one fixed role.', array['counts for school hours'], 15, false, false, true, 'Varies', 'https://www.uclahealth.org/volunteer/westwood/student-programs/high-school-students', 'https://www.uclahealth.org/volunteer/westwood/student-programs/high-school-students', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000009', 'c5000000-0000-4000-8000-000000000009', 'Join the Keck Medicine Summer Youth Program', 'medicine', 'High school students 16 to 17 gain hands-on volunteer experience at either Keck Hospital or USC Norris Cancer Hospital over the summer. It is a good fit if you are interested in oncology or academic medicine specifically.', array['counts for school hours'], 16, false, false, true, 'Summer program', 'https://www.keckmedicine.org/volunteer/', 'https://www.keckmedicine.org/volunteer/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000010', 'c5000000-0000-4000-8000-000000000010', 'Join Pasadena Humane Kid and Teen Volunteers', 'animals', 'Pasadena Humane runs a specific volunteer track for kids and teens under 15, letting younger volunteers get real shelter experience with age-appropriate tasks and adult supervision. It is one of the few shelter programs in the region open to volunteers this young.', array['family friendly', 'recurring'], 0, false, false, true, '2 hrs', 'https://pasadenahumane.org/get-involved/volunteer/kid-teen-volunteers-under-15/', 'https://pasadenahumane.org/get-involved/volunteer/kid-teen-volunteers-under-15/', '2026-01-01T00:00:00Z', 'Pasadena', 'CA'),
  ('c6000000-0000-4000-8000-000000000011', 'c5000000-0000-4000-8000-000000000011', 'Volunteer at an LA County Animal Shelter', 'animals', 'Volunteers 16 and up help with animal socialization, cleaning, and enrichment activities at LA County shelters across the region. It is a solid option once you are old enough, since it covers multiple shelter locations countywide.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://animalcare.lacounty.gov/volunteer-opportunities/', 'https://animalcare.lacounty.gov/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000012', 'c5000000-0000-4000-8000-000000000012', 'Volunteer with Pet Orphans of Southern California', 'animals', 'Volunteers 14 and up help with shelter care, socializing animals, and supporting adoption events, with community-service-friendly scheduling for students who need documented hours. It is a good middle-ground shelter option between the youngest and adult-only programs.', array['counts for school hours', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://petorphans.org/volunteer/', 'https://petorphans.org/volunteer/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000013', 'c5000000-0000-4000-8000-000000000013', 'Volunteer with spcaLA', 'animals', 'Volunteers support shelter operations and can also get involved with spcaLA humane education programs that teach kindness toward animals to younger students. It is a good pick if you are interested in animal welfare education, not just direct animal care.', array['recurring'], 14, false, false, true, '2-3 hrs', 'https://spcala.com/volunteer/volunteer-services/', 'https://spcala.com/volunteer/volunteer-services/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000014', 'c5000000-0000-4000-8000-000000000014', 'Join The Mission Continues LA Platoon', 'veterans', 'The LA Platoon works in the LA Promise Zone, taking on projects that improve school grounds and expand educational opportunities for youth in underserved areas. Veteran and community volunteers work side by side, connecting through regular service projects and social events.', array['leadership role', 'good for crews'], 18, false, false, true, 'Varies', 'https://www.missioncontinues.org/service-platoon/Los-Angeles/', 'https://www.missioncontinues.org/service-platoon/Los-Angeles/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000015', 'c5000000-0000-4000-8000-000000000015', 'Tutor a Student in Reading', 'education', 'Volunteers commit to a little over an hour a week tutoring a student one-on-one in reading, either in person or online, with flexible weekly time slots to fit a school or work schedule. It is a strong option if you want measurable, one-on-one literacy impact.', array['recurring', 'counts for school hours'], 14, false, false, true, '1 hr / week', 'https://readingpartners.org/volunteer-in-los-angeles/', 'https://readingpartners.org/volunteer-in-los-angeles/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000016', 'c5000000-0000-4000-8000-000000000016', 'Become a Step Up Tutor', 'education', 'Tutors are paired with a single student for consistent, twice-weekly one-on-one online sessions, with full training provided before you start. Because sessions happen online, it is a good option even if you cannot easily get to a physical tutoring site.', array['recurring', 'counts for school hours'], 16, false, false, true, '1 hr, 2x / week', 'https://www.stepuptutoring.org/', 'https://www.stepuptutoring.org/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000017', 'c5000000-0000-4000-8000-000000000017', 'Tutor a Student Experiencing Homelessness', 'education', 'Volunteers provide 1:1 academic tutoring and mentorship to students experiencing homelessness, often meeting at shelters, motels, or other locations where families are staying. It is a meaningful option if you want your tutoring to directly address educational gaps caused by housing instability.', array['recurring'], 16, false, false, true, '1-2 hrs / week', 'https://schoolonwheels.org/', 'https://schoolonwheels.org/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA'),
  ('c6000000-0000-4000-8000-000000000018', 'c5000000-0000-4000-8000-000000000018', 'Volunteer or Coach with Special Olympics SoCal', 'sports', 'Team volunteers can start at age 14, coaches at 16, and advanced coaches at 18, with full training provided so no prior coaching background is required. It is a great long-term option if you want to build toward a real coaching role over a few seasons.', array['recurring', 'leadership role'], 14, false, false, true, '1-2 hrs / week', 'https://sosc.org/volunteer/', 'https://sosc.org/volunteer/', '2026-01-01T00:00:00Z', 'Los Angeles', 'CA')
on conflict (id) do nothing;

