insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('d7000000-0000-4000-8000-000000000001', null, 'Greater Chicago Food Depository', 'The largest hunger-relief organization in the Chicago area, distributing food through a network of hundreds of pantries and programs across Cook County.', 'https://www.chicagosfoodbank.org', 'https://www.google.com/s2/favicons?domain=www.chicagosfoodbank.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 11, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000002', null, 'Nourishing Hope Chicago', 'A Chicago nonprofit fighting food insecurity by packing groceries and responding to ongoing community food needs.', 'https://nourishinghopechi.org', 'https://www.google.com/s2/favicons?domain=nourishinghopechi.org&sz=128', 'food', array['family friendly', 'good for crews'], false, false, 0, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000003', null, 'Chicago Park District', 'The public agency managing Chicago parks and natural areas, running a Community Stewardship Program with more than 400 volunteer days a year across 35-plus sites.', 'https://www.chicagoparkdistrict.com', 'https://www.google.com/s2/favicons?domain=www.chicagoparkdistrict.com&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000004', null, 'Chicago Parks Foundation', 'A nonprofit supporting Chicago parks through cleanup supplies, Green Teams, and community-led park improvement projects.', 'https://www.chicagoparksfoundation.org', 'https://www.google.com/s2/favicons?domain=www.chicagoparksfoundation.org&sz=128', 'environment', array['good for crews', 'leadership role', 'outdoors'], false, false, 0, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000005', null, 'Chicago Conservation Corps', 'A City of Chicago program training residents to protect and steward the city natural resources through hands-on environmental projects.', 'https://www.chicago.gov', 'https://www.google.com/s2/favicons?domain=www.chicago.gov&sz=128', 'environment', array['outdoors', 'good for crews'], false, false, 14, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000006', null, 'Lurie Children''s Hospital', 'One of the leading pediatric hospitals in the country, relying on volunteers throughout the facility to support patients and families.', 'https://www.luriechildrens.org', 'https://www.google.com/s2/favicons?domain=www.luriechildrens.org&sz=128', 'medicine', array['counts for school hours'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000007', null, 'UChicago Medicine AdventHealth', 'A hospital system serving Chicago south suburbs, welcoming teen, college, and adult volunteers across multiple facilities.', 'https://www.uchicagomedicineadventhealth.org', 'https://www.google.com/s2/favicons?domain=www.uchicagomedicineadventhealth.org&sz=128', 'medicine', array['recurring'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000008', null, 'Endeavor Health', 'A large Chicago-area hospital network offering high school volunteers exposure to hospital departments and healthcare career paths.', 'https://www.endeavorhealth.org', 'https://www.google.com/s2/favicons?domain=www.endeavorhealth.org&sz=128', 'medicine', array['counts for school hours'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000009', null, 'Field Museum', 'One of the largest natural history museums in the world, running a teen volunteer program that puts students right on the museum floor.', 'https://www.fieldmuseum.org', 'https://www.google.com/s2/favicons?domain=www.fieldmuseum.org&sz=128', 'art', array['recurring', 'leadership role'], false, false, 14, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000010', null, 'PAWS Chicago', 'The largest no-kill animal welfare organization in Chicago, running adoption centers and a medical center that rely heavily on volunteers.', 'https://www.pawschicago.org', 'https://www.google.com/s2/favicons?domain=www.pawschicago.org&sz=128', 'animals', array['family friendly', 'recurring'], false, false, 12, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000011', null, 'Anti-Cruelty Society', 'A Chicago animal welfare organization offering both a beginner-friendly shelter service day and a more advanced seasonal teen volunteer program.', 'https://anticruelty.org', 'https://www.google.com/s2/favicons?domain=anticruelty.org&sz=128', 'animals', array['family friendly'], false, false, 0, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000012', null, 'Chicago Animal Care and Control', 'The city agency operating Chicago animal shelters, caring for dogs, cats, and small animals with volunteer support for enrichment and adoption.', 'https://www.chicago.gov', 'https://www.google.com/s2/favicons?domain=www.chicago.gov&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000013', null, 'Bernie''s Book Bank', 'A Chicago nonprofit that collects, sorts, and distributes millions of free books each year to under-resourced children across the region.', 'https://www.berniesbookbank.org', 'https://www.google.com/s2/favicons?domain=www.berniesbookbank.org&sz=128', 'education', array['family friendly', 'good for crews', 'creative work'], false, false, 0, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000014', null, 'Tutoring Chicago', 'A Chicago nonprofit pairing volunteer tutors with students in 1st through 12th grade for consistent, weekly one-on-one academic support.', 'https://www.tutoringchicago.org', 'https://www.google.com/s2/favicons?domain=www.tutoringchicago.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000015', null, 'Chicago Teen Mentors', 'A peer-to-peer nonprofit where teen volunteers themselves provide free 1-on-1 tutoring over Zoom to Chicago Public Schools students in math and reading.', 'https://www.chicagoteenmentors.org', 'https://www.google.com/s2/favicons?domain=www.chicagoteenmentors.org&sz=128', 'education', array['recurring', 'counts for school hours', 'leadership role'], false, false, 14, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000016', null, 'Chicago Westside Sports', 'A youth sports nonprofit on Chicago west side that relies on community coaches, including teens and off-duty police officers, to mentor young athletes.', 'https://www.chicagowestsidesports.org', 'https://www.google.com/s2/favicons?domain=www.chicagowestsidesports.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000017', null, 'Lost Boyz Inc.', 'A Chicago youth development nonprofit using sports, mentoring, and tutoring to support young people in underserved neighborhoods.', 'https://lostboyzinc.org', 'https://www.google.com/s2/favicons?domain=lostboyzinc.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'both', false),
  ('d7000000-0000-4000-8000-000000000018', null, 'Northside Chicago AYSO', 'The Northside Chicago chapter of the American Youth Soccer Organization, running recreational youth soccer leagues staffed largely by volunteer coaches and referees.', 'https://www.northsidechicagoayso.com', 'https://www.google.com/s2/favicons?domain=www.northsidechicagoayso.com&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'IL', 'Chicago', true, true, 'ongoing', false),
  ('d7000000-0000-4000-8000-000000000019', null, 'Chicago Veterans', 'A Chicago nonprofit connecting veterans to community, purpose, and support through peer programs and volunteer service projects.', 'https://chicagovets.org', 'https://www.google.com/s2/favicons?domain=chicagovets.org&sz=128', 'veterans', array['recurring'], false, false, 18, 'United States', 'IL', 'Chicago', true, true, 'both', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('d8000000-0000-4000-8000-000000000001', 'd7000000-0000-4000-8000-000000000001', 'Sort Food at the Chicago Food Depository', 'food', 'Youth volunteers ages 11 to 15 can join regular volunteer sessions with one adult required for every 6 to 8 youth, and volunteers 16 and up can register and attend independently. Sessions typically involve sorting and repacking donated food for distribution across the city.', array['good for crews', 'family friendly'], 11, false, false, true, '2-3 hrs', 'https://www.chicagosfoodbank.org/get-involved/volunteer/', 'https://www.chicagosfoodbank.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000002', 'd7000000-0000-4000-8000-000000000002', 'Pack Groceries with Nourishing Hope', 'food', 'Volunteers pack groceries and sort donated food to meet ongoing needs in the community, with shifts open to individuals, families, and groups. It is one of the more family-friendly hunger-relief options in the city, welcoming volunteers of any age with a guardian.', array['family friendly', 'good for crews'], 0, false, false, true, '2 hrs', 'https://nourishinghopechi.org/volunteer/', 'https://nourishinghopechi.org/volunteer/', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000003', 'd7000000-0000-4000-8000-000000000003', 'Join a Natural Areas Stewardship Day', 'environment', 'Public stewardship days welcome anyone regardless of age, background, or experience, though minors under 13 need a parent or guardian present. Tasks vary by season and site, from trail maintenance and planting to invasive species removal, and dedicated Apprentice Steward roles are open to volunteers 16 and up who want a full year commitment.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://www.chicagoparkdistrict.com/get-involved/volunteer/natural-areas-community-stewardship-days', 'https://www.chicagoparkdistrict.com/get-involved/volunteer/natural-areas-community-stewardship-days', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000004', 'd7000000-0000-4000-8000-000000000004', 'Host or Join a Chicago Parks Green Team Cleanup', 'environment', 'The Foundation provides free clean-up supplies for small groups to run their own park cleanups, and encourages recurring cleanups at the same park from June through October. It is a great option if you want to organize a project with friends or a club rather than joining an existing one.', array['good for crews', 'leadership role', 'outdoors'], 0, false, false, true, '2 hrs', 'https://www.chicagoparksfoundation.org/volunteer', 'https://www.chicagoparksfoundation.org/volunteer', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000005', 'd7000000-0000-4000-8000-000000000005', 'Join the Chicago Conservation Corps Explorer Track', 'environment', 'The Explorer track offers short-term, year-round volunteer projects that protect Chicago green spaces and natural resources, making it easy to try a project without a long commitment. It is a good entry point before committing to a longer stewardship role elsewhere in the city.', array['outdoors', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.chicago.gov/city/en/depts/cdot/supp_info/chicago_conservationcorpsexplorertrack.html', 'https://www.chicago.gov/city/en/depts/cdot/supp_info/chicago_conservationcorpsexplorertrack.html', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000006', 'd7000000-0000-4000-8000-000000000006', 'Volunteer at Lurie Children Hospital', 'medicine', 'Volunteers 16 and up support activities throughout the hospital, with most high school opportunities concentrated in a structured summer program. It is a strong choice if you are considering pediatrics or nursing specifically.', array['counts for school hours'], 16, false, false, true, 'Varies', 'https://www.luriechildrens.org/en/ways-to-help/volunteer/become-a-hospital-volunteer/', 'https://www.luriechildrens.org/en/ways-to-help/volunteer/become-a-hospital-volunteer/', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000007', 'd7000000-0000-4000-8000-000000000007', 'Volunteer at UChicago Medicine AdventHealth', 'medicine', 'Teens 16 and 17 can volunteer alongside college students and adults, taking on roles like escorting patients, greeting visitors, or supporting business offices during set shift blocks throughout the day. It is a flexible option since shifts are offered in several short blocks rather than one long commitment.', array['recurring'], 16, false, false, true, '4 hrs / shift', 'https://www.uchicagomedicineadventhealth.org/volunteering', 'https://www.uchicagomedicineadventhealth.org/volunteering', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000008', 'd7000000-0000-4000-8000-000000000008', 'Explore Healthcare Careers as an Endeavor Health Volunteer', 'medicine', 'High school volunteers get placed in departments that match their interests, gaining direct exposure to how a hospital runs and helping them figure out if a healthcare career is the right fit. It is a good option if you are still deciding between different health career paths.', array['counts for school hours'], 16, false, false, true, 'Varies', 'https://www.endeavorhealth.org/give/volunteer', 'https://www.endeavorhealth.org/give/volunteer', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000009', 'd7000000-0000-4000-8000-000000000009', 'Become a Field Museum Teen Volunteer', 'art', 'Teen volunteers split their time between the Crown Family PlayLab and facilitating interpretive carts in Stanley Field Hall, engaging visitors and sharing science stories throughout the museum. It is a great fit if you enjoy public speaking and science communication.', array['recurring', 'leadership role'], 14, false, false, true, '2-3 hrs / week', 'https://www.fieldmuseum.org/activity/teen-volunteers', 'https://www.fieldmuseum.org/activity/teen-volunteers', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000010', 'd7000000-0000-4000-8000-000000000010', 'Join PAWS Chicago Junior Volunteers (PAWS JV)', 'animals', 'Volunteers ages 12 to 17 can join PAWS JV to help keep shelter animals clean, safe, and loved, with shifts available on weekdays and weekends at the Lincoln Park adoption center or the Little Village medical center. Volunteers under 18 need to attend with a parent or guardian.', array['family friendly', 'recurring'], 12, false, false, true, '2-3 hrs', 'https://www.pawschicago.org/how-to-help/volunteer/volunteer-opportunities/junior-volunteers', 'https://www.pawschicago.org/how-to-help/volunteer/volunteer-opportunities/junior-volunteers', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000011', 'd7000000-0000-4000-8000-000000000011', 'Join Anti-Cruelty Shelter Service Day', 'animals', 'Shelter Service Day is a beginner teen volunteer program for a quick, low-commitment shelter experience, while an advanced seasonal program during CPS school breaks requires an application and offers more responsibility. It is a good starting point before working up to more involved shelter roles.', array['family friendly'], 0, false, false, true, '2 hrs', 'https://anticruelty.org/volunteer', 'https://anticruelty.org/volunteer', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000012', 'd7000000-0000-4000-8000-000000000012', 'Volunteer at Chicago Animal Care and Control', 'animals', 'Volunteers work hands-on with dogs, cats, and small animals like rabbits and guinea pigs, providing exercise and enrichment, plus supporting matchmaking, events, and marketing efforts. It is a good fit if you want variety beyond just direct animal care.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://www.chicago.gov/city/en/depts/cacc/supp_info/volunteering_at_chicagoanimalcareandcontrol.html', 'https://www.chicago.gov/city/en/depts/cacc/supp_info/volunteering_at_chicagoanimalcareandcontrol.html', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000013', 'd7000000-0000-4000-8000-000000000013', 'Sort and Sticker Books at Bernie Book Bank', 'education', 'Weekly volunteer sessions involve stickering, sorting books by grade level and quality, and bagging them for distribution, with reservations opening about two months in advance. It welcomes volunteers of all ages and abilities and is one of the easiest drop-in literacy projects in the city.', array['family friendly', 'good for crews', 'creative work'], 0, false, false, true, '2 hrs', 'https://www.berniesbookbank.org/volunteer/', 'https://www.berniesbookbank.org/volunteer/', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000014', 'd7000000-0000-4000-8000-000000000014', 'Become a Tutoring Chicago Volunteer', 'education', 'Tutors meet with the same student weekly for 90-minute digital or in-person sessions starting each September, with applications accepted on a rolling basis through February. It is a strong pick if you want a full-year, one-on-one mentoring relationship.', array['recurring', 'counts for school hours'], 16, false, false, true, '90 min / week', 'https://www.tutoringchicago.org/volunteer/', 'https://www.tutoringchicago.org/volunteer/', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000015', 'd7000000-0000-4000-8000-000000000015', 'Tutor CPS Students as a Teen Mentor', 'education', 'Because tutors are teens themselves, sessions are scheduled in convenient after-school blocks from 5 to 6 pm and 7 to 8 pm, tutoring students in grades 3 through 10 in math and reading over Zoom. It is one of the few programs built specifically for high schoolers to tutor other students.', array['recurring', 'counts for school hours', 'leadership role'], 14, false, false, true, '1 hr / week', 'https://www.chicagoteenmentors.org/', 'https://www.chicagoteenmentors.org/', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000016', 'd7000000-0000-4000-8000-000000000016', 'Coach with Chicago Westside Sports', 'sports', 'Coach-mentors range from age 16 to 76, with opportunities for a single event or a weekly season-long commitment, and no prior coaching experience is required. It is a good option if you want coaching experience alongside a genuinely mixed-age volunteer team.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://www.chicagowestsidesports.org/get-involved', 'https://www.chicagowestsidesports.org/get-involved', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000017', 'd7000000-0000-4000-8000-000000000017', 'Coach, Mentor, or Tutor with Lost Boyz Inc.', 'sports', 'Volunteers can coach a team, mentor a young person one-on-one, tutor academically, or simply show up to support and cheer on a team at games. It is a flexible option if you want to combine sports with mentoring rather than picking just one.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://lostboyzinc.org/', 'https://lostboyzinc.org/', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000018', 'd7000000-0000-4000-8000-000000000018', 'Coach or Referee for AYSO Soccer', 'sports', 'AYSO provides free training to every coach and referee, so no soccer background is required, just enthusiasm and a positive attitude working with kids. It is a great pick if you want a season-long commitment with a specific sport rather than a one-time event.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs / week', 'https://www.northsidechicagoayso.com/Default.aspx?tabid=931979', 'https://www.northsidechicagoayso.com/Default.aspx?tabid=931979', '2026-01-01T00:00:00Z', 'Chicago', 'IL'),
  ('d8000000-0000-4000-8000-000000000019', 'd7000000-0000-4000-8000-000000000019', 'Volunteer with Chicago Veterans', 'veterans', 'Chicago Veterans runs volunteer opportunities throughout the year supporting its peer community programs and service events for local veterans. It is a good fit if you want your service specifically directed at supporting the veteran community in Chicago.', array['recurring'], 18, false, false, true, 'Varies', 'https://chicagovets.org/volunteer/', 'https://chicagovets.org/volunteer/', '2026-01-01T00:00:00Z', 'Chicago', 'IL')
on conflict (id) do nothing;

