insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('e9000000-0000-4000-8000-000000000001', null, 'Houston Food Bank', 'The largest food bank in the country by pounds of food distributed, serving a wide network of pantries and programs across southeast Texas.', 'https://www.houstonfoodbank.org', 'https://www.google.com/s2/favicons?domain=www.houstonfoodbank.org&sz=128', 'food', array['good for crews', 'family friendly', 'leadership role'], false, false, 6, 'United States', 'TX', 'Houston', true, true, 'both', false),
  ('e9000000-0000-4000-8000-000000000002', null, 'Buffalo Bayou Partnership', 'The nonprofit steward of Buffalo Bayou Park, caring for the trails, natural areas, and waterway that runs through the heart of Houston.', 'https://www.buffalobayou.org', 'https://www.google.com/s2/favicons?domain=www.buffalobayou.org&sz=128', 'environment', array['outdoors', 'good for crews', 'family friendly'], false, false, 9, 'United States', 'TX', 'Houston', true, true, 'both', false),
  ('e9000000-0000-4000-8000-000000000003', null, 'Houston Parks and Recreation Department', 'The city department managing parks across Houston, relying on volunteers for everything from coaching youth sports to neighborhood park cleanups.', 'https://www.houstontx.gov', 'https://www.google.com/s2/favicons?domain=www.houstontx.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'TX', 'Houston', true, true, 'both', false),
  ('e9000000-0000-4000-8000-000000000004', null, 'Houston Parks Board', 'A nonprofit partner working alongside the city to improve and expand Houston park system through funding, planning, and volunteer-powered projects.', 'https://houstonparksboard.org', 'https://www.google.com/s2/favicons?domain=houstonparksboard.org&sz=128', 'environment', array['outdoors', 'good for crews'], false, false, 0, 'United States', 'TX', 'Houston', true, true, 'both', false),
  ('e9000000-0000-4000-8000-000000000005', null, 'The Health Museum', 'A hands-on science museum in the Houston Museum District focused on health and the human body, welcoming volunteers year-round.', 'https://thehealthmuseum.org', 'https://www.google.com/s2/favicons?domain=thehealthmuseum.org&sz=128', 'art', array['recurring'], false, false, 15, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000006', null, 'Texas Children''s Hospital', 'One of the largest children hospitals in the country, running a Summer Junior Volunteer program each year across its Houston-area campuses.', 'https://www.texaschildrenspeople.org', 'https://www.google.com/s2/favicons?domain=www.texaschildrenspeople.org&sz=128', 'medicine', array['counts for school hours'], false, false, 15, 'United States', 'TX', 'Houston', true, true, 'one-time', false),
  ('e9000000-0000-4000-8000-000000000007', null, 'HCA Houston Healthcare', 'A network of hospitals across the Houston area running a summer VolunTEEN program for local high school students.', 'https://www.hcahoustonhealthcare.com', 'https://www.google.com/s2/favicons?domain=www.hcahoustonhealthcare.com&sz=128', 'medicine', array['counts for school hours'], false, false, 16, 'United States', 'TX', 'Houston', true, true, 'one-time', false),
  ('e9000000-0000-4000-8000-000000000008', null, 'Harris Health System', 'The public safety-net health system for Harris County, running a Summer Junior Volunteer Program for local students each year.', 'https://www.harrishealth.org', 'https://www.google.com/s2/favicons?domain=www.harrishealth.org&sz=128', 'medicine', array['counts for school hours'], false, false, 15, 'United States', 'TX', 'Houston', true, true, 'one-time', false),
  ('e9000000-0000-4000-8000-000000000009', null, 'Memorial Hermann', 'One of the largest not-for-profit health systems in Texas, with volunteer programs across its Houston-area hospital campuses.', 'https://volunteer.memorialhermann.org', 'https://www.google.com/s2/favicons?domain=volunteer.memorialhermann.org&sz=128', 'medicine', array['recurring'], false, false, 16, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000010', null, 'Citizens for Animal Protection', 'A Houston-area no-kill animal shelter and adoption center running a monthly Teen Service Day for younger volunteers.', 'https://www.cap4pets.org', 'https://www.google.com/s2/favicons?domain=www.cap4pets.org&sz=128', 'animals', array['recurring', 'family friendly'], false, false, 14, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000011', null, 'Houston Humane Society', 'A long-standing Houston animal welfare organization offering a range of volunteer roles for young animal lovers and adults alike.', 'https://www.houstonhumane.org', 'https://www.google.com/s2/favicons?domain=www.houstonhumane.org&sz=128', 'animals', array['family friendly', 'recurring'], false, false, 10, 'United States', 'TX', 'Houston', true, true, 'both', false),
  ('e9000000-0000-4000-8000-000000000012', null, 'BARC Animal Shelter and Adoptions', 'The City of Houston public animal shelter, caring for thousands of animals a year with the help of a large volunteer base.', 'https://www.houstontx.gov', 'https://www.google.com/s2/favicons?domain=www.houstontx.gov&sz=128', 'animals', array['recurring'], false, false, 13, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000013', null, 'Houston Pets Alive!', 'A Houston nonprofit focused on reducing shelter euthanasia by rescuing, fostering, and finding homes for at-risk animals.', 'https://www.houstonpetsalive.org', 'https://www.google.com/s2/favicons?domain=www.houstonpetsalive.org&sz=128', 'animals', array['family friendly', 'recurring'], false, false, 13, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000014', null, 'YMCA of Greater Houston', 'A major Houston nonprofit running youth sports leagues, after-school programs, and a teen leadership program called Y Teen L.I.F.E.', 'https://ymcahouston.org', 'https://www.google.com/s2/favicons?domain=ymcahouston.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'TX', 'Houston', true, true, 'both', false),
  ('e9000000-0000-4000-8000-000000000015', null, 'Easter Seals Greater Houston', 'A Houston nonprofit serving veterans, children, and adults with disabilities through therapy, employment, and mentoring programs.', 'https://eastersealshouston.org', 'https://www.google.com/s2/favicons?domain=eastersealshouston.org&sz=128', 'community', array['recurring', 'leadership role'], false, false, 16, 'United States', 'TX', 'Houston', true, true, 'both', false),
  ('e9000000-0000-4000-8000-000000000016', null, 'Breakthrough Houston', 'An education nonprofit that recruits current high school students to tutor middle schoolers, built specifically around a student-teaching-student model.', 'https://breakthroughhouston.org', 'https://www.google.com/s2/favicons?domain=breakthroughhouston.org&sz=128', 'education', array['recurring', 'leadership role', 'counts for school hours'], false, false, 14, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000017', null, 'PAIR Houston', 'A Houston mentoring nonprofit that matches volunteers one-on-one with 11th grade students for weekly college and career guidance.', 'https://www.pairhouston.org', 'https://www.google.com/s2/favicons?domain=www.pairhouston.org&sz=128', 'education', array['recurring', 'leadership role'], false, false, 16, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000018', null, 'Nehemiah Center', 'A Houston community center running after-school enrichment and college-prep tutoring programs for students from kindergarten through high school.', 'https://www.nehemiahcenterhouston.org', 'https://www.google.com/s2/favicons?domain=www.nehemiahcenterhouston.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000019', null, 'Houston reVision', 'A Houston nonprofit that mentors teens connected to the juvenile justice system, using consistent one-on-one relationships to help them build a different future.', 'https://www.houstonrevision.org', 'https://www.google.com/s2/favicons?domain=www.houstonrevision.org&sz=128', 'community', array['recurring', 'leadership role'], false, false, 16, 'United States', 'TX', 'Houston', true, true, 'ongoing', false),
  ('e9000000-0000-4000-8000-000000000020', null, 'Big Brothers Big Sisters Lone Star', 'The Houston-area chapter of Big Brothers Big Sisters, matching adult mentors in one-to-one friendships with young people who benefit from extra support.', 'https://bbbstx.org', 'https://www.google.com/s2/favicons?domain=bbbstx.org&sz=128', 'community', array['leadership role', 'recurring'], false, false, 18, 'United States', 'TX', 'Houston', true, true, 'ongoing', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('ea000000-0000-4000-8000-000000000001', 'e9000000-0000-4000-8000-000000000001', 'Sort Food with School and Youth Groups', 'food', 'Minors can volunteer starting at age 6 in the Portwall Warehouse (16 for the Keegan Kitchen), sorting and packaging food while learning the value of community service. The Food Bank also runs a 16-week leadership program for students 16 to 18 that leads toward joining Apple Corps, its dedicated volunteer leadership group.', array['good for crews', 'family friendly', 'leadership role'], 6, false, false, true, '2-3 hrs', 'https://www.houstonfoodbank.org/ways-to-give/give-time/volunteerwithhfb/schoolyouthgroups/', 'https://www.houstonfoodbank.org/ways-to-give/give-time/volunteerwithhfb/schoolyouthgroups/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000002', 'e9000000-0000-4000-8000-000000000002', 'Restore Buffalo Bayou Park', 'environment', 'On the third Saturday of each month, volunteers ages 9 and up (with a chaperone 21 or older, one adult per ten youth) take on gardening, invasive species removal, and trash pickup to keep the bayou healthy. It is a solid recurring monthly option if you want a consistent outdoor project.', array['outdoors', 'good for crews', 'family friendly'], 9, false, false, true, '2-3 hrs', 'https://www.buffalobayou.org/volunteer/', 'https://www.buffalobayou.org/volunteer/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000003', 'e9000000-0000-4000-8000-000000000003', 'Volunteer with Houston Parks and Recreation', 'environment', 'Hundreds of volunteers support programs and activities ranging from coaching youth sports teams to cleanup projects at neighborhood parks across the city. Reach out through the department contact to find current openings near you.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.houstontx.gov/parks/wanttohelp.html', 'https://www.houstontx.gov/parks/wanttohelp.html', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000004', 'e9000000-0000-4000-8000-000000000004', 'Volunteer with Houston Parks Board', 'environment', 'Volunteers support park improvement projects across the city, from plantings to cleanup days, helping expand green space access throughout Houston. It is a good complement to the city Parks Department if you want to see the nonprofit side of park development.', array['outdoors', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://houstonparksboard.org/volunteer/', 'https://houstonparksboard.org/volunteer/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000005', 'e9000000-0000-4000-8000-000000000005', 'Volunteer at The Health Museum', 'art', 'Volunteers help run exhibits and support programs for visitors of all ages exploring health and the human body, with the museum welcoming individuals, student groups, and corporate teams year-round. All volunteers must be at least 15.', array['recurring'], 15, false, false, true, '2-3 hrs', 'https://thehealthmuseum.org/join-give/volunteer/', 'https://thehealthmuseum.org/join-give/volunteer/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000006', 'e9000000-0000-4000-8000-000000000006', 'Join Texas Children Summer Junior Volunteers', 'medicine', 'High school students 15 to 17 can apply (typically in February) for placements like hospital playrooms, craft carts, guest services, and outpatient play areas across Texas Children various campuses. It is a strong option if you want to work directly with young patients in a lighter, activity-based role.', array['counts for school hours'], 15, false, false, true, 'Summer program', 'https://www.texaschildrenspeople.org/summer-junior-volunteers/', 'https://www.texaschildrenspeople.org/summer-junior-volunteers/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000007', 'e9000000-0000-4000-8000-000000000007', 'Join the HCA Houston VolunTEEN Program', 'medicine', 'The VolunTEEN program runs each summer from roughly June to August, giving high schoolers exposure to hospital operations across HCA Houston facilities. It is a good option if your summer schedule is open and you want structured hospital experience.', array['counts for school hours'], 16, false, false, true, 'Summer program', 'https://www.hcahoustonhealthcare.com/about-us/volunteers', 'https://www.hcahoustonhealthcare.com/about-us/volunteers', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000008', 'e9000000-0000-4000-8000-000000000008', 'Join the Harris Health Junior Volunteer Program', 'medicine', 'The Junior Volunteer Program places high schoolers in support roles across Harris Health facilities over the summer, giving a look at how a large public hospital system serves the community. It is a good pick if you want healthcare exposure with a public-service angle.', array['counts for school hours'], 15, false, false, true, 'Summer program', 'https://www.harrishealth.org/give-hh/volunteer/Pages/summer-junior-volunteer-program.aspx', 'https://www.harrishealth.org/give-hh/volunteer/Pages/summer-junior-volunteer-program.aspx', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000009', 'e9000000-0000-4000-8000-000000000009', 'Volunteer at a Memorial Hermann Hospital', 'medicine', 'Volunteers 16 and up support patient services and hospital operations at Memorial Hermann campuses around the Houston area, with opportunities varying by location. It is worth checking which specific campus is closest to you when applying.', array['recurring'], 16, false, false, true, 'Varies', 'https://volunteer.memorialhermann.org/', 'https://volunteer.memorialhermann.org/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000010', 'e9000000-0000-4000-8000-000000000010', 'Join CAP Teen Service Day', 'animals', 'Teen Service Day runs monthly for volunteers 14 and up, with ages 14-15 co-volunteering alongside a parent or guardian and 16 and up able to volunteer independently. It is a predictable, once-a-month option if you want a recurring shelter shift without a weekly commitment.', array['recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.cap4pets.org/support-us/volunteer', 'https://www.cap4pets.org/support-us/volunteer', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000011', 'e9000000-0000-4000-8000-000000000011', 'Volunteer at Houston Humane Society', 'animals', 'Youth volunteers can take part in select roles suited to their age, from animal socialization to event support, alongside the organization broader adult volunteer program. It is a solid general-purpose option if you love animals but are not sure which specific shelter task fits you yet.', array['family friendly', 'recurring'], 10, false, false, true, '2-3 hrs', 'https://www.houstonhumane.org/volunteer/become-a-volunteer', 'https://www.houstonhumane.org/volunteer/become-a-volunteer', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000012', 'e9000000-0000-4000-8000-000000000012', 'Volunteer at BARC Animal Shelter', 'animals', 'Volunteers 13-15 must always volunteer with a parent or guardian, while those 16-17 can volunteer independently after attending an orientation with a parent or guardian. It is one of the most structured age-tiered shelter programs in the city, making it easy to know exactly what is expected at your age.', array['recurring'], 13, false, false, true, '2-3 hrs', 'https://www.houstontx.gov/barc/volunteer.html', 'https://www.houstontx.gov/barc/volunteer.html', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000013', 'e9000000-0000-4000-8000-000000000013', 'Volunteer with Houston Pets Alive!', 'animals', 'Volunteers 13 and up can help with animal care and adoption events, with those 13-17 required to volunteer alongside a parent or guardian at all times. It is a good option if you specifically want to support at-risk, high-need animals rather than general shelter care.', array['family friendly', 'recurring'], 13, false, false, true, '2-3 hrs', 'https://www.houstonpetsalive.org/volunteer/', 'https://www.houstonpetsalive.org/volunteer/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000014', 'e9000000-0000-4000-8000-000000000014', 'Coach Youth Sports at the Houston YMCA', 'sports', 'Volunteer coaches help kids build game skills, sportsmanship, and fair play across YMCA youth sports leagues throughout the city. The YMCA also runs Y Teen L.I.F.E., a program specifically empowering teens through community involvement, if coaching is not quite the fit.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://ymcahouston.org/volunteer', 'https://ymcahouston.org/volunteer', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000015', 'e9000000-0000-4000-8000-000000000015', 'Volunteer with Easter Seals Greater Houston', 'community', 'Volunteers support programs for veterans and people with disabilities, including the RAMP mentoring program pairing volunteers with youth who benefit from consistent adult support. It is a good option if you want your service to specifically reach both veterans and the disability community.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://eastersealshouston.org/volunteer/', 'https://eastersealshouston.org/volunteer/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000016', 'e9000000-0000-4000-8000-000000000016', 'Tutor Middle Schoolers as a High Schooler', 'education', 'Breakthrough Houston specifically seeks motivated high school students to serve as academic tutors for middle schoolers in math, English, languages, science, and social studies. It is one of the only programs built entirely around teens teaching younger students, rather than adults tutoring teens.', array['recurring', 'leadership role', 'counts for school hours'], 14, false, false, true, 'Varies', 'https://breakthroughhouston.org/vol-student/', 'https://breakthroughhouston.org/vol-student/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000017', 'e9000000-0000-4000-8000-000000000017', 'Mentor an 11th Grader with PAIR Houston', 'education', 'Volunteers meet with their matched student once a week, after school or on weekends, helping with college and career exploration alongside general homework help. It is a good fit if you want a single, consistent mentee relationship focused specifically on the college-prep years.', array['recurring', 'leadership role'], 16, false, false, true, '1 hr / week', 'https://www.pairhouston.org/volunteer/', 'https://www.pairhouston.org/volunteer/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000018', 'e9000000-0000-4000-8000-000000000018', 'Tutor at the Nehemiah Center', 'education', 'Volunteers tutor and mentor students in the After School Enrichment Program (grades K-5) or the College Prep Program (grades 6-12), creating an account through the site to get started. It is a good option if you want to pick between working with younger kids or older students preparing for college.', array['recurring', 'counts for school hours'], 14, false, false, true, 'Varies', 'https://www.nehemiahcenterhouston.org/volunteer/', 'https://www.nehemiahcenterhouston.org/volunteer/', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000019', 'e9000000-0000-4000-8000-000000000019', 'Mentor a Teen Through Houston reVision', 'community', 'Volunteers meet with a matched teen for one hour a week, in schools, juvenile justice settings, or at community night events, building the kind of steady relationship that research shows can genuinely change outcomes. It is a serious, meaningful option if you specifically want to support at-risk youth.', array['recurring', 'leadership role'], 16, false, false, true, '1 hr / week', 'https://www.houstonrevision.org/volunteer', 'https://www.houstonrevision.org/volunteer', '2026-01-01T00:00:00Z', 'Houston', 'TX'),
  ('ea000000-0000-4000-8000-000000000020', 'e9000000-0000-4000-8000-000000000020', 'Be a Big in Houston', 'community', 'Bigs commit to spending a few hours a month with their matched Little doing everyday activities and building a consistent friendship over at least a year. Because it is an ongoing one-on-one relationship with a minor, mentors must be adults, making this a great one to bookmark for college.', array['leadership role', 'recurring'], 18, false, false, true, '2-4 hrs / month', 'https://bbbstx.org/houston/', 'https://bbbstx.org/houston/', '2026-01-01T00:00:00Z', 'Houston', 'TX')
on conflict (id) do nothing;

