insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('fb000000-0000-4000-8000-000000000001', null, 'Phoenix Rescue Mission', 'A Phoenix nonprofit addressing hunger, homelessness, and addiction, running the Hope for Hunger Food Bank alongside outreach and recovery programs.', 'https://phoenixrescuemission.org', 'https://www.google.com/s2/favicons?domain=phoenixrescuemission.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 12, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000002', null, 'United Food Bank', 'A regional food bank serving Eastern Arizona communities, distributing millions of pounds of food each year through partner agencies.', 'https://unitedfoodbank.org', 'https://www.google.com/s2/favicons?domain=unitedfoodbank.org&sz=128', 'food', array['family friendly', 'good for crews'], false, false, 5, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000003', null, 'Arizona Food Bank Network', 'The statewide network coordinating food banks across Arizona to fight hunger, connecting volunteers to member food banks throughout the state.', 'https://azfoodbanks.org', 'https://www.google.com/s2/favicons?domain=azfoodbanks.org&sz=128', 'food', array['good for crews'], false, false, 14, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000004', null, 'Homeless Youth Connection', 'A Phoenix-area nonprofit supporting youth experiencing homelessness with basic needs, mentoring, and resources to help them stay in school.', 'https://hycaz.org', 'https://www.google.com/s2/favicons?domain=hycaz.org&sz=128', 'community', array['recurring'], false, false, 16, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000005', null, 'City of Phoenix Parks and Recreation', 'The city department managing more than 35,000 acres of desert preserve and park land across Phoenix, relying on volunteers for trail and preserve stewardship.', 'https://www.phoenix.gov', 'https://www.google.com/s2/favicons?domain=www.phoenix.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000006', null, 'Keep Phoenix Beautiful', 'A Phoenix nonprofit running community gardens, tree plantings, and litter and recycling cleanups to keep the city clean and green.', 'https://www.keepphxbeautiful.org', 'https://www.google.com/s2/favicons?domain=www.keepphxbeautiful.org&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000007', null, 'Arizona State Parks', 'The state agency managing Arizona network of state parks, offering volunteer roles across conservation, education, and park operations.', 'https://azstateparks.com', 'https://www.google.com/s2/favicons?domain=azstateparks.com&sz=128', 'environment', array['outdoors'], false, false, 14, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000008', null, 'Natural Restorations', 'An Arizona nonprofit running volunteer cleanup and restoration events at natural areas and waterways across the state.', 'http://www.naturalrestorations.org', 'https://www.google.com/s2/favicons?domain=www.naturalrestorations.org&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000009', null, 'HonorHealth', 'A major Phoenix-area hospital network running a seven-week Summer Teen Volunteer Program each year across its medical centers.', 'https://www.honorhealth.com', 'https://www.google.com/s2/favicons?domain=www.honorhealth.com&sz=128', 'medicine', array['counts for school hours', 'leadership role'], false, false, 15, 'United States', 'AZ', 'Phoenix', true, true, 'one-time', false),
  ('fb000000-0000-4000-8000-000000000010', null, 'Phoenix Children''s', 'A leading pediatric hospital system in Arizona, relying on volunteers to support young patients and their families across its facilities.', 'https://phoenixchildrens.org', 'https://www.google.com/s2/favicons?domain=phoenixchildrens.org&sz=128', 'medicine', array['counts for school hours'], false, false, 15, 'United States', 'AZ', 'Phoenix', true, true, 'ongoing', false),
  ('fb000000-0000-4000-8000-000000000011', null, 'Dignity Health St. Joseph''s Hospital', 'A major Phoenix hospital running a Summer Junior Volunteer Program that lets teenagers explore healthcare careers while helping patients and staff.', 'https://www.dignityhealth.org', 'https://www.google.com/s2/favicons?domain=www.dignityhealth.org&sz=128', 'medicine', array['counts for school hours'], false, false, 15, 'United States', 'AZ', 'Phoenix', true, true, 'one-time', false),
  ('fb000000-0000-4000-8000-000000000012', null, 'University of Arizona College of Medicine - Phoenix', 'The Phoenix campus of the University of Arizona medical school, offering volunteer opportunities connected to its academic medical programs.', 'https://phoenixmed.arizona.edu', 'https://www.google.com/s2/favicons?domain=phoenixmed.arizona.edu&sz=128', 'medicine', array['recurring'], false, false, 16, 'United States', 'AZ', 'Phoenix', true, true, 'ongoing', false),
  ('fb000000-0000-4000-8000-000000000013', null, 'Arizona Humane Society', 'One of the largest animal welfare organizations in Arizona, helping around 20,000 sick, injured, and abused pets every year.', 'https://www.azhumane.org', 'https://www.google.com/s2/favicons?domain=www.azhumane.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'AZ', 'Phoenix', true, true, 'ongoing', false),
  ('fb000000-0000-4000-8000-000000000014', null, 'Arizona Animal Welfare League', 'The oldest and largest no-kill animal shelter in Arizona, founded in 1971, rehoming and rehabilitating thousands of rescue animals each year.', 'https://aawl.org', 'https://www.google.com/s2/favicons?domain=aawl.org&sz=128', 'animals', array['recurring', 'family friendly'], false, false, 16, 'United States', 'AZ', 'Phoenix', true, true, 'ongoing', false),
  ('fb000000-0000-4000-8000-000000000015', null, 'Humane Society of Central Arizona', 'A regional animal shelter and adoption center serving Central Arizona communities outside the immediate Phoenix core.', 'https://humanesocietycentralaz.org', 'https://www.google.com/s2/favicons?domain=humanesocietycentralaz.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'AZ', 'Phoenix', true, true, 'ongoing', false),
  ('fb000000-0000-4000-8000-000000000016', null, 'Maricopa County Animal Care and Control', 'The public animal shelter system for Maricopa County, caring for thousands of dogs and cats a year across its Phoenix-area locations.', 'https://www.maricopa.gov', 'https://www.google.com/s2/favicons?domain=www.maricopa.gov&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'AZ', 'Phoenix', true, true, 'ongoing', false),
  -- Note: "The Mission Continues" is NOT re-inserted here as a new org - it
  -- already exists as a single organization from the LA batch (migration 010,
  -- id c5000000-...-14). The Phoenix opportunity below attaches to that same
  -- org instead of creating a duplicate organization row.
  ('fb000000-0000-4000-8000-000000000018', null, 'Youth for Troops', 'An all-volunteer nonprofit built around young people supporting troops and veterans through letters, care packages, and outreach.', 'https://youthfortroops.org', 'https://www.google.com/s2/favicons?domain=youthfortroops.org&sz=128', 'veterans', array['family friendly', 'creative work'], false, false, 0, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000019', null, 'Special Olympics Arizona', 'The Arizona chapter of Special Olympics, providing year-round sports training and competition for athletes with intellectual disabilities across the state.', 'https://specialolympicsarizona.org', 'https://www.google.com/s2/favicons?domain=specialolympicsarizona.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 14, 'United States', 'AZ', 'Phoenix', true, true, 'both', false),
  ('fb000000-0000-4000-8000-000000000020', null, 'City of Phoenix Volunteer Portal', 'The official city volunteer portal listing openings across Phoenix departments, including youth sports coaching positions.', 'https://volunteer.phoenix.gov', 'https://www.google.com/s2/favicons?domain=volunteer.phoenix.gov&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'AZ', 'Phoenix', true, true, 'both', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('fc000000-0000-4000-8000-000000000001', 'fb000000-0000-4000-8000-000000000001', 'Pack Food Bags at Hope for Hunger Food Bank', 'food', 'Volunteers pack bags of food and supplies for mobile pantries and community outreach events, with a minimum age of 12 for general service and 14 for food service roles. All minors need a signed Youth Volunteer Authorization and must be accompanied by an adult.', array['good for crews', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://phoenixrescuemission.org/get-involved/volunteer/', 'https://phoenixrescuemission.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000002', 'fb000000-0000-4000-8000-000000000002', 'Pack Emergency Food Bags', 'food', 'Kids as young as 5 can join emergency food bag packing shifts alongside a parent, and teens 16 to 17 can volunteer independently at any shift with a signed waiver. It is one of the most family-friendly food bank options in the region for younger siblings to join too.', array['family friendly', 'good for crews'], 5, false, false, true, '2-3 hrs', 'https://unitedfoodbank.org/volunteer/', 'https://unitedfoodbank.org/volunteer/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000003', 'fb000000-0000-4000-8000-000000000003', 'Get Involved with the Arizona Food Bank Network', 'food', 'The network connects volunteers to hands-on opportunities at its member food banks across Arizona, making it a good first stop if you want to compare a few different food bank options in one place. It is especially useful if you are outside central Phoenix and want to find the closest member bank.', array['good for crews'], 14, false, false, true, 'Varies', 'https://azfoodbanks.org/take-action/get-involved/', 'https://azfoodbanks.org/take-action/get-involved/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000004', 'fb000000-0000-4000-8000-000000000004', 'Support Homeless Youth in Phoenix', 'community', 'Volunteers 16 and up can serve unaccompanied, while younger volunteers must be accompanied by an adult, supporting programs that help homeless youth stay connected to school and stable resources. It is a meaningful option if you specifically want to support young people close to your own age facing housing instability.', array['recurring'], 16, false, false, true, 'Varies', 'https://hycaz.org/get-involved/', 'https://hycaz.org/get-involved/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000005', 'fb000000-0000-4000-8000-000000000005', 'Steward Phoenix Desert Preserves and Trails', 'environment', 'Volunteers help monitor and protect preserve lands through trail monitoring, maintaining trailhead gates, picking up litter, and answering visitor questions. It is a strong option if you specifically want to help protect Phoenix desert landscape rather than a traditional grassy park.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.phoenix.gov/administration/departments/parks/volunteer-parks.html', 'https://www.phoenix.gov/administration/departments/parks/volunteer-parks.html', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000006', 'fb000000-0000-4000-8000-000000000006', 'Volunteer with Keep Phoenix Beautiful', 'environment', 'Regular volunteer events run at two community gardens plus recycling events, tree plantings, and litter cleanups around the city. It is an easy, low-commitment way to try a few different types of environmental projects before picking a favorite.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2 hrs', 'https://www.keepphxbeautiful.org/volunteer', 'https://www.keepphxbeautiful.org/volunteer', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000007', 'fb000000-0000-4000-8000-000000000007', 'Volunteer at an Arizona State Park', 'environment', 'Volunteer roles can be tailored to your interest, whether that is trail and facility maintenance, ecological restoration, or visitor education, at parks across the state. It is a good option if you want variety across several different Arizona parks rather than sticking to one city location.', array['outdoors'], 14, false, false, true, 'Varies', 'https://azstateparks.com/volunteer', 'https://azstateparks.com/volunteer', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000008', 'fb000000-0000-4000-8000-000000000008', 'Join a Natural Restorations Cleanup Event', 'environment', 'Events run throughout the year at different natural areas, with a public calendar making it easy to find and register for the next cleanup near you. It is a flexible, drop-in-friendly way to pick up outdoor volunteer hours whenever your schedule allows.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2-3 hrs', 'http://www.naturalrestorations.org/new-page-3', 'http://www.naturalrestorations.org/new-page-3', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000009', 'fb000000-0000-4000-8000-000000000009', 'Join the HonorHealth Summer Teen Volunteer Program', 'medicine', 'Open to Arizona juniors and seniors who have completed 10th grade and are at least 15, the program combines hands-on volunteer service with more than 20 M.E.D. career-exploration sessions featuring physicians and clinical staff. It is a strong pick if you want structured career exploration alongside your volunteer hours.', array['counts for school hours', 'leadership role'], 15, false, false, true, 'Summer program', 'https://www.honorhealth.com/community/volunteer-opportunities/teen', 'https://www.honorhealth.com/community/volunteer-opportunities/teen', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000010', 'fb000000-0000-4000-8000-000000000010', 'Volunteer at Phoenix Children''s', 'medicine', 'Volunteers support patients and families through activities, comfort care, and hospital operations, with most teen opportunities concentrated in structured programs. It is a good option if you are specifically drawn to pediatric care.', array['counts for school hours'], 15, false, false, true, 'Varies', 'https://phoenixchildrens.org/about-us/ways-help/volunteering', 'https://phoenixchildrens.org/about-us/ways-help/volunteering', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000011', 'fb000000-0000-4000-8000-000000000011', 'Join the St. Joseph''s Junior Volunteer Program', 'medicine', 'Junior volunteers help patients and staff over the summer while meeting people, observing healthcare professionals, and building experience that can strengthen college and scholarship applications. It is a well-established program with a long track record in the Phoenix area.', array['counts for school hours'], 15, false, false, true, 'Summer program', 'https://www.dignityhealth.org/arizona/locations/stjosephs/ways-to-give/volunteer-information/junior-volunteer-summer-program', 'https://www.dignityhealth.org/arizona/locations/stjosephs/ways-to-give/volunteer-information/junior-volunteer-summer-program', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000012', 'fb000000-0000-4000-8000-000000000012', 'Volunteer with UArizona College of Medicine - Phoenix', 'medicine', 'Volunteer roles connect to the college academic and community health programs, offering a look at medical education from a university perspective rather than a single hospital. It is a good option if you are specifically interested in medical school down the road.', array['recurring'], 16, false, false, true, 'Varies', 'https://phoenixmed.arizona.edu/faq/volunteer-opportunities', 'https://phoenixmed.arizona.edu/faq/volunteer-opportunities', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000013', 'fb000000-0000-4000-8000-000000000013', 'Volunteer with Arizona Humane Society', 'animals', 'Volunteers 16 and up complete an online orientation and commit to one shift a week for at least three months, helping care for thousands of pets that pass through the organization each year. It is a serious, structured option once you meet the age minimum.', array['recurring'], 16, false, false, true, '2-3 hrs / week', 'https://www.azhumane.org/become-a-volunteer/', 'https://www.azhumane.org/become-a-volunteer/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000014', 'fb000000-0000-4000-8000-000000000014', 'Volunteer with Arizona Animal Welfare League', 'animals', 'Volunteers help care for and socialize shelter animals, with fostering also available if you want to help from home. It is a good option if you are interested in the no-kill movement specifically.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://aawl.org/content/volunteer', 'https://aawl.org/content/volunteer', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000015', 'fb000000-0000-4000-8000-000000000015', 'Volunteer at Humane Society of Central Arizona', 'animals', 'Volunteers 16 and 17 can serve on their own with parent or guardian consent, helping with shelter care and adoption support. It is a good pick if you are located further out from downtown Phoenix.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://humanesocietycentralaz.org/volunteer/', 'https://humanesocietycentralaz.org/volunteer/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000016', 'fb000000-0000-4000-8000-000000000016', 'Volunteer with MCACC', 'animals', 'Volunteers support animal care, socialization, and adoption events across Maricopa County shelter locations. It is a solid countywide option if you want to help no matter which part of the Phoenix metro you live in.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://www.maricopa.gov/294/Volunteer', 'https://www.maricopa.gov/294/Volunteer', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000017', 'c5000000-0000-4000-8000-000000000014', 'Join The Mission Continues Phoenix Platoon', 'veterans', 'The Phoenix Platoon welcomes anyone with a passion for service, regardless of veteran status, working alongside nonprofit partners and community leaders on local projects. It is a good option if you want to serve alongside veterans on community-focused projects.', array['leadership role', 'good for crews'], 18, false, false, true, 'Varies', 'https://www.missioncontinues.org/service-platoon/Phoenix/', 'https://www.missioncontinues.org/service-platoon/Phoenix/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000018', 'fb000000-0000-4000-8000-000000000018', 'Support Troops and Veterans as a Youth Volunteer', 'veterans', 'Volunteers of any age can help assemble care packages, write letters, and support outreach events honoring troops and veterans. It is one of the few veteran-support organizations built specifically around youth participation.', array['family friendly', 'creative work'], 0, false, false, true, 'Varies', 'https://youthfortroops.org/', 'https://youthfortroops.org/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000019', 'fb000000-0000-4000-8000-000000000019', 'Volunteer with Special Olympics Arizona', 'sports', 'Volunteers are needed as coaches, trainers, officials, event organizers, and Unified Partners who play alongside athletes directly. No sports expertise is required, since training and support are provided for every role.', array['recurring', 'leadership role'], 14, false, false, true, '1-2 hrs / week', 'https://specialolympicsarizona.org/volunteer/', 'https://specialolympicsarizona.org/volunteer/', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ'),
  ('fc000000-0000-4000-8000-000000000020', 'fb000000-0000-4000-8000-000000000020', 'Coach Youth Sports Through the City of Phoenix', 'sports', 'The city portal posts open youth sports coaching positions alongside other city volunteer roles, making it easy to browse current openings in one place. It is a good option if coaching interests you but you are not tied to one specific league yet.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://volunteer.phoenix.gov/custom/501/volunteer_home', 'https://volunteer.phoenix.gov/custom/501/volunteer_home', '2026-01-01T00:00:00Z', 'Phoenix', 'AZ')
